package com.nbi.report.model;

public class User {
    private final String username;
    private final String role; // CUSTOMER or ADMIN

        public User(String username, String role) { this.username = username;
        this.role = role; }
    public String getUsername() { return username; }
    public String getRole() { return role; }
    public boolean hasRole(String r) { return role.equals(r); }
}
