package com.nbi.report.security;

import com.nbi.report.model.User;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
public class TokenService {
    // token -> user ; "EXPIRED-..." simulates an expired/invalid token.
    private final Map<String, User> tokens = new HashMap<>();

    public TokenService() {
        tokens.put("RAJESH-CUST", new User("rajesh", "CUSTOMER"));
        tokens.put("ADMIN-OPS",  new User("ops-admin", "ADMIN"));
    }

    public boolean isValid(String token) {
        return token != null && tokens.containsKey(token); // EXPIRED token → invalid
    }
    public User userOf(String token) { return tokens.get(token); }
}
```

```java
// ─── File: src/main/java/com/nbi/report/controller/ReportController.java ───
package com.nbi.report.controller;

import com.nbi.report.model.User;
import com.nbi.report.security.TokenService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/reports")
public class ReportController {

    private final TokenService tokenService;
    public ReportController(TokenService tokenService) { this.tokenService = tokenService; }

    // Admin-only fraud report.
    @GetMapping("/fraud")
    public ResponseEntity<String> fraudReport(
            @RequestHeader(value = "Authorization", required = false) String token) {

        // STEP 1 — authenticate. Missing/expired/invalid token → 401.
        if (!tokenService.isValid(token)) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .header("WWW-Authenticate", "Bearer")
                    .body("Authentication required (token missing or expired)"); // 401
        }

        // STEP 2 — authorize. Authenticated but wrong role → 403.
        User user = tokenService.userOf(token);
        if (!user.hasRole("ADMIN")) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN)
                    .body("Forbidden: ADMIN role required"); // 403
        }

        return ResponseEntity.ok("Fraud report for " + user.getUsername()); // 200
    }

    // Highly sensitive internal account — hide existence from unauthorized users (404 not 403).
    @GetMapping("/internal/{id}")
    public ResponseEntity<String> internal(
            @RequestHeader(value = "Authorization", required = false) String token,
            @PathVariable String id) {

        if (!tokenService.isValid(token))
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build(); // 401

        User user = tokenService.userOf(token);
        if (!user.hasRole("ADMIN")) {
            // Deliberate: return 404 to avoid leaking that this resource exists.
            return ResponseEntity.notFound().build(); // 404 (privacy choice over 403)
        }
        return ResponseEntity.ok("Internal account " + id);
    }
}
```
